parameters.jsCode:
const output = $input.first().json.stdout;

const match = output.match(/([A-Fa-f0-9]{64}\.zip)/);

if (!match) {
  return [];
}

return [{
  json: {
    zip_path: "E:\\" + match[1]
  }
}];

